using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Configuration;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatBuilder =>
    chatBuilder.UseOpenAIChatClient(
        builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18"));

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

var notepad = new Notepad();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(
        (string query) =>
        {
            // Simulated web search returning results for the query
            return $"""
                Search results for "{query}":
                1. [Wikipedia] {query} is a broad topic with many facets. Key developments include recent advances and historical context.
                2. [TechReview] Latest analysis shows significant progress in {query}, with experts predicting continued growth.
                3. [ScienceDaily] New research on {query} reveals unexpected connections to related fields.
                """;
        },
        "SearchWeb",
        "Searches the web for information on a given query. Returns a list of relevant results."),

    AIFunctionFactory.Create(
        (string title, string content) =>
        {
            notepad.AddNote(title, content);
            return $"Note saved: \"{title}\"";
        },
        "TakeNote",
        "Saves a research note with a title and content. Use this to record key findings during research."),

    AIFunctionFactory.Create(
        () => notepad.GetAllNotes(),
        "GetNotes",
        "Retrieves all saved research notes as a formatted string."),
};

var agent = chatClient.AsAIAgent(
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    instructions: """
        You are a research assistant. When given a topic:
        1. Search the web for relevant information using multiple queries.
        2. Take notes on key findings using the TakeNote tool.
        3. After gathering enough information, retrieve your notes and provide a comprehensive summary.
        Be thorough — perform at least 2-3 searches with different queries to cover the topic well.
        """,
    tools: tools);

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the impact of artificial intelligence on healthcare";

Console.WriteLine($"🔍 Researching: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await agent.RunAsync(messages);

Console.WriteLine("📋 Research Summary:");
Console.WriteLine(new string('─', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('─', 50));

if (notepad.HasNotes)
{
    Console.WriteLine("\n📝 Research Notes:");
    Console.WriteLine(notepad.GetAllNotes());
}

