using System.Text;

namespace ResearchAgent;

/// <summary>
/// A simple note-taking tool that stores research notes in memory.
/// </summary>
public sealed class Notepad
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public bool HasNotes => _notes.Count > 0;

    public void AddNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes recorded yet.";
        }

        var sb = new StringBuilder();
        for (int i = 0; i < _notes.Count; i++)
        {
            var (title, content, timestamp) = _notes[i];
            sb.AppendLine($"[{i + 1}] {title} ({timestamp:HH:mm:ss UTC})");
            sb.AppendLine($"    {content}");
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

